$ErrorActionPreference = 'Stop'
$root = (Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
$fields = 'public FakeCPH CPH=new FakeCPH(); public System.Collections.Generic.Dictionary<string,object> args=new System.Collections.Generic.Dictionary<string,object>();'
$timer = (Get-Content -Raw (Join-Path $root 'modules/named-timers/streamerbot/named-timers-engine.cs')).Replace('public class CPHInline {', ('public class TimerInline {'+$fields))
$reminder = (Get-Content -Raw (Join-Path $root 'modules/reminders/streamerbot/reminders-engine.cs')).Replace('public class CPHInline {', ('public class ReminderInline {'+$fields))
$redeem = (Get-Content -Raw (Join-Path $root 'modules/redeem-checklist/streamerbot/redeem-checklist-engine.cs')).Replace('public class CPHInline {', ('public class RedeemInline {'+$fields))
$fake = @'
using System;using System.Linq;using System.Collections.Generic;using Newtonsoft.Json.Linq;
public class FakeGlobal{public string VariableName;public object Value;}
public class FakeCPH{
 public Dictionary<string,object> Globals=new Dictionary<string,object>(),Arguments=new Dictionary<string,object>();public List<string> Broadcasts=new List<string>();
 public int Writes,FailAt,Effects;public bool Reject,ThrowResolve;
 public T GetGlobalVar<T>(string key,bool persist){return Globals.ContainsKey(key)?(T)Globals[key]:default(T);}
 public void SetGlobalVar(string key,object value,bool persist){if(++Writes==FailAt)throw new Exception("Synthetic persistence failure");Globals[key]=value;}
 public List<FakeGlobal> GetGlobalVarValues(bool persist){return Globals.Select(p=>new FakeGlobal{VariableName=p.Key,Value=p.Value}).ToList();}
 public void SetArgument(string key,object value){Arguments[key]=value;}public void WebsocketBroadcastJson(string s){Broadcasts.Add(s);}
 public bool TwitchRedemptionCancel(string reward,string id){return Resolve();}public bool TwitchRedemptionFulfill(string reward,string id){return Resolve();}
 bool Resolve(){Effects++;if(ThrowResolve)throw new Exception("Synthetic uncertain response");return !Reject;}
 public void LogError(string text){}public void LogInfo(string text){}
}
public static class Tests{
 static void Check(bool v,string text){if(!v)throw new Exception(text);}
 static JObject Payload(FakeCPH c,string key){return JObject.Parse((string)c.Globals[key])["payload"] as JObject;}
 static void Run(TimerInline e,string mode,string request,string title="work",string seconds="60"){e.args=new Dictionary<string,object>{{"namedTimersMode",mode},{"requestId",request},{"timerTitle",title},{"timerSeconds",seconds}};e.Execute();}
 static void Run(ReminderInline e,string mode,string request,string id="open",string message="New private message"){e.args=new Dictionary<string,object>{{"reminderMode",mode},{"requestId",request},{"id",id},{"userName","synthetic"},{"user","Synthetic"},{"rawInput",message}};e.Execute();}
 static void Run(RedeemInline e,string request,string resolution="refund"){e.args=new Dictionary<string,object>{{"redeemMode","phone-resolve"},{"requestId",request},{"redemptionId","pending"},{"resolution",resolution}};e.Execute();}
 static ReminderInline Reminder(){var e=new ReminderInline();e.CPH.Globals["portable.reminders.private"]="{\"payload\":{\"retained\":\"keep\",\"items\":[{\"id\":\"open\",\"targetKey\":\"synthetic\",\"message\":\"Open private text\",\"status\":\"open\"},{\"id\":\"history\",\"message\":\"Completed private history\",\"status\":\"completed\"}]}}";return e;}
 static RedeemInline Redeem(){var e=new RedeemInline();e.CPH.Globals["portable.redeems.state"]="{\"payload\":{\"retained\":\"keep\",\"pending\":[{\"redemptionId\":\"pending\",\"rewardId\":\"reward\",\"rewardTitle\":\"Reward\",\"userName\":\"Synthetic\",\"userInput\":\"Private input\"}],\"history\":[{\"redemptionId\":\"history\",\"status\":\"completed\"}]}}";return e;}
 public static void RunAll(){
  var t=new TimerInline();Run(t,"phone-add","timer-one");string end=(string)t.CPH.Globals["timer_end_work"];Run(t,"phone-add","timer-one");Check((string)t.CPH.Globals["timer_end_work"]==end,"Duplicate timer request extended twice");Run(t,"health","");Check((string)Payload(t.CPH,"portable.timers.state")["phoneDeckResults"]["timer-one"]["status"]=="completed","Publish lost timer acknowledgement");Check(!t.CPH.Globals.ContainsKey("managedLanguageRedemptionsJson"),"Phone timer duplicated language routing");Run(t,"phone-add","reserved","German");Check(!t.CPH.Globals.ContainsKey("timer_end_german"),"Reserved language timer bypassed routing");Run(t,"phone-add","fraction","bad","1.5");Check(!t.CPH.Globals.ContainsKey("timer_end_bad"),"Fractional seconds were accepted");
  foreach(int fail in new[]{1,2,3}){var e=new TimerInline();e.CPH.FailAt=fail;Run(e,"phone-add","failed");if(fail==1)Check(!e.CPH.Globals.ContainsKey("timer_end_work"),"Failed intent still created timer");else{string before=e.CPH.Globals.ContainsKey("timer_end_work")?(string)e.CPH.Globals["timer_end_work"]:"";var restarted=new TimerInline();restarted.CPH.Globals=e.CPH.Globals;Run(restarted,"phone-add","failed");Check((restarted.CPH.Globals.ContainsKey("timer_end_work")?(string)restarted.CPH.Globals["timer_end_work"]:"")==before,"Uncertain timer request replayed after restart");Check((string)Payload(restarted.CPH,"portable.timers.state")["phoneDeckResults"]["failed"]["status"]!="completed","Failed timer persistence reported completion");}}
  var r=Reminder();Run(r,"phone-add","add");var p=Payload(r.CPH,"portable.reminders.private");Check(((JArray)p["items"]).Count==3,"Phone reminder add failed");Run(r,"phone-add","add");Check(((JArray)Payload(r.CPH,"portable.reminders.private")["items"]).Count==3,"Duplicate reminder add replayed");Run(r,"phone-complete","done");Run(r,"initialize","");p=Payload(r.CPH,"portable.reminders.private");Check((int)p["phoneDeck"]["openCount"]==1&&(string)p["retained"]=="keep","Reminder completion lost private data");Check((string)p["phoneDeckResults"]["done"]["status"]=="completed","Initialize erased reminder acknowledgement");Check(((JArray)p["items"]).Count==3,"Reminder completion deleted history");Check(r.CPH.Broadcasts.All(b=>!b.Contains("private text")&&!b.Contains("private history")&&!b.Contains("New private")),"Reminder content leaked into public broadcast");Run(r,"phone-add","invalid","open","");Check((string)Payload(r.CPH,"portable.reminders.private")["phoneDeckResults"]["invalid"]["status"]=="error","Invalid reminder did not reject before mutation");
  var uncertain=Reminder();uncertain.CPH.FailAt=4;Run(uncertain,"phone-add","lost");var restartedR=Reminder();restartedR.CPH.Globals=uncertain.CPH.Globals;Run(restartedR,"phone-add","lost");Check(((JArray)Payload(restartedR.CPH,"portable.reminders.private")["items"]).Count==3,"Reminder replayed after partial persistence");Check((string)Payload(restartedR.CPH,"portable.reminders.private")["phoneDeckResults"]["lost"]["status"]=="running","Unknown reminder incorrectly confirmed");
  foreach(string resolution in new[]{"complete","refund"}){var d=Redeem();Run(d,"resolve",resolution);Run(d,"resolve",resolution);p=Payload(d.CPH,"portable.redeems.state");Check(d.CPH.Effects==1&&(int)p["phoneDeck"]["pendingCount"]==0,"Redemption dispatch duplicated or not removed");Check(((JArray)p["history"]).Count==2&&(string)p["retained"]=="keep","Redemption history/config lost");Check((string)p["phoneDeckResults"]["resolve"]["status"]=="completed","Redemption completion missing");d.args=new Dictionary<string,object>{{"redeemMode","initialize"}};d.Execute();Check((string)Payload(d.CPH,"portable.redeems.state")["phoneDeckResults"]["resolve"]["status"]=="completed","Refresh lost durable result");}
  foreach(int fail in new[]{1,2,3}){var d=Redeem();d.CPH.FailAt=fail;Run(d,"failed");int effects=d.CPH.Effects;Check(effects==(fail==1?0:1),"Redemption side effect before durable intent");if(fail>1){var restarted=new RedeemInline();restarted.CPH.Globals=d.CPH.Globals;Run(restarted,"failed");Check(restarted.CPH.Effects==0,"Uncertain redemption replayed after restart");}}
  var rejected=Redeem();rejected.CPH.Reject=true;Run(rejected,"rejected");Check((string)Payload(rejected.CPH,"portable.redeems.state")["phoneDeckResults"]["rejected"]["status"]=="error","Rejected Twitch response reported complete");var unknown=Redeem();unknown.CPH.ThrowResolve=true;Run(unknown,"unknown");Check((string)Payload(unknown.CPH,"portable.redeems.state")["phoneDeckResults"]["unknown"]["status"]=="unknown","Thrown Twitch response must remain unknown");var malformed=Redeem();Run(malformed,"bad","other");Check(malformed.CPH.Effects==0,"Malformed resolution triggered Twitch");
  var redeem=Redeem();System.Threading.Tasks.Parallel.For(0,12,i=>{var e=new RedeemInline();e.CPH=redeem.CPH;Run(e,"concurrent-"+i);});Check(redeem.CPH.Effects==1,"Concurrent redemption resolutions dispatched twice");
  var shared=new TimerInline();System.Threading.Tasks.Parallel.For(0,20,i=>{var e=new TimerInline();e.CPH.Globals=shared.CPH.Globals;Run(e,"phone-add","concurrent-"+i,"timer"+i);});Check(shared.CPH.Globals.Keys.Count(k=>k.StartsWith("timer_end_"))==20,"Concurrent timer creation lost state");
  var reminders=Reminder();System.Threading.Tasks.Parallel.For(0,10,i=>{var e=new ReminderInline();e.CPH.Globals=reminders.CPH.Globals;Run(e,"phone-add","concurrent-"+i);});Check(((JArray)Payload(reminders.CPH,"portable.reminders.private")["items"]).Count==12,"Concurrent reminder additions lost state");
 }
}
'@
$refs=@((Get-ChildItem -LiteralPath (Join-Path $PSHOME 'ref') -Filter '*.dll').FullName)+(Join-Path $PSHOME 'Newtonsoft.Json.dll')
Add-Type -TypeDefinition ('namespace PhoneBacklogTest{'+$fake+'}namespace PhoneBacklogTest{'+$timer+'}namespace PhoneBacklogTest{'+$reminder+'}namespace PhoneBacklogTest{'+$redeem+'}') -ReferencedAssemblies $refs -CompilerOptions '/nowarn:1701,1702'
[PhoneBacklogTest.Tests]::RunAll()
Write-Output 'Actual Session 9 C# passed: private unfinished projections, timer validation/language exclusion, serialized concurrency, complete/refund rejection/unknown outcomes, persisted intent/dedup/restart, failed saves and acknowledgements surviving initialization. All effects synthetic.'
